INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Anforderungsspezifikation immer ein formelles Dokument?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch informell sein"}, {"text": "Ja", "correct": false, "because": "Flexibel je nach Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Anforderungsspezifikation?', 3, '[{"text": "Klarheit über Anforderungen schaffen", "correct": true, "because": "Definiert Projektumfang"}, {"text": "Kosten reduzieren", "correct": false, "because": "Indirekter Effekt"}, {"text": "Design festlegen", "correct": false, "because": "Spätere Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Anforderungsspezifikation?', 5, '[{"text": "Funktionale Anforderungen", "correct": true, "because": "Beschreibt Systemverhalten"}, {"text": "Nicht-funktionale Anforderungen", "correct": true, "because": "Definiert Qualität"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein technischer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie dient als Basis für Tests. b) Sie ist nur für Entwickler gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Stakeholder relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer Anforderungsspezifikation?', 4, '[{"text": "Stakeholder-Bedürfnisse", "correct": false, "because": "Kern der Anforderungen"}, {"text": "Messbarkeit", "correct": false, "because": "Erleichtert Validierung"}, {"text": "Firmenlogo", "correct": true, "because": "Irrelevant für Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Anforderungsspezifikation änderbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibel während Projektlaufzeit"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung gehört typischerweise zur Spezifikation?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Nicht-funktionale Anforderung"}, {"text": "Entwickleranzahl", "correct": false, "because": "Projektmanagement"}, {"text": "Budget", "correct": false, "because": "Kostenplanung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Erstellung einer Anforderungsspezifikation?', 5, '[{"text": "Anforderungserhebung", "correct": true, "because": "Sammelt Bedürfnisse"}, {"text": "Priorisierung", "correct": true, "because": "Sortiert nach Wichtigkeit"}, {"text": "Code-Implementierung", "correct": false, "because": "Spätere Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Anforderungsspezifikation ist verbindlich. b) Sie enthält nur technische Details. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch nicht-technische Aspekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Anforderungsspezifikation unwichtig?', 4, '[{"text": "Klarheit", "correct": false, "because": "Vermeidet Missverständnisse"}, {"text": "Nachvollziehbarkeit", "correct": false, "because": "Wichtig für Validierung"}, {"text": "Schriftart", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Anforderungsspezifikation vollständig sein?', 2, '[{"text": "Ja", "correct": true, "because": "Deckt alle Anforderungen ab"}, {"text": "Nein", "correct": false, "because": "Unvollständig unbrauchbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine gute Anforderungsspezifikation?', 4, '[{"text": "Klarheit für Entwickler", "correct": true, "because": "Reduziert Unsicherheiten"}, {"text": "Basis für Abnahme", "correct": true, "because": "Definiert Erfolgskriterien"}, {"text": "Geringere Kosten", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Anforderungsspezifikation nur für große Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Projekte nützlich"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in einer Anforderungsspezifikation?', 3, '[{"text": "Präzision", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität wichtiger"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sie enthält Akzeptanzkriterien. b) Sie ist nur für Kunden gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Team relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Anforderungsspezifikation?', 5, '[{"text": "Missverständnisse", "correct": true, "because": "Unklarheit führt zu Fehlern"}, {"text": "Verzögerungen", "correct": true, "because": "Korrekturen nötig"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in einer Anforderungsspezifikation unwichtig?', 3, '[{"text": "Anforderungspriorität", "correct": false, "because": "Steuert Umsetzung"}, {"text": "Systemgrenzen", "correct": false, "because": "Definiert Umfang"}, {"text": "Teamgröße", "correct": true, "because": "Kein Spezifikationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Anforderungsspezifikation agil genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Iterativ anpassbar"}, {"text": "Nein", "correct": false, "because": "Nicht statisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob sie rechtlich bindend ist?', 2, '[{"text": "Ja", "correct": true, "because": "Vertraglich festgelegt"}, {"text": "Nein", "correct": false, "because": "Abhängig, aber oft bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine klare Anforderungsspezifikation?', 4, '[{"text": "Use Cases", "correct": true, "because": "Beschreibt Szenarien"}, {"text": "Code-Beispiele", "correct": false, "because": "Spätere Phase"}, {"text": "Budgetplanung", "correct": false, "because": "Anderer Bereich"}]');
